  (2, '첫 만남이 있는 아침, 평소보다 일찍 깼다면 뭘 하고 싶나요?', array['이불 속에서 기지개를 길게 켜요.', '창문을 열고 바람부터 쐬요.', '꿈이 흩어지기 전에 적어 둬요.']),
  (10, '데이트 중 가방에서 꺼내 빌려주면 반가울 물건은 뭘까요?', array['실밥이 나왔을 때 쓰는 쪽가위요.', '누구에게든 빌려줄 수 있는 펜이요.', '물건이 늘어나도 든든한 장바구니요.']),
