  (99, '취미가 다른 두 사람의 공동 작업실에는 무엇부터 들여놓을까요?', array['종이를 반듯하게 잘라 주는 재단기요.', '고장 난 물건도 열어 볼 드라이버 세트요.', '천을 넓게 펼칠 수 있는 큰 탁자요.']),
  (106, '데이트를 같이 준비할 때 신이 나서 맡게 되는 역할이 있나요?', array['둘 다 편하게 갈 길을 알아봐요.', '망설이던 체험에 빈자리가 있는지 봐요.', '기다리는 동안 할 짧은 놀이를 준비해요.']),
