  (177, '좋아하는 사람의 취미 생활을 좀 더 편하게 해 줄 물건은요?', array['책이 펴진 채로 있어 주는 독서대요.', '물병 뚜껑을 잡아 주는 고무 패드요.', '자주 쓰는 문장을 찍어 주는 도장이요.']),
  (182, '귀여운 꿈 이야기를 들려주는 상대에게 어떤 질문을 덧붙이고 싶나요?', array['그 장면에 나왔다면 난 뭐였을까요?', '다음 장면은 어떻게 이어지면 좋을까요?', '그 꿈에 제목을 지으면 뭐라고 할까요?']),
