  (284, '둘이 제한 시간 안에 탑을 쌓아야 한다면 어떤 재료가 재밌을까요?', array['종이컵을 뒤집어 아슬아슬하게 올려요.', '빈 상자를 넓이순으로 포개요.', '책 사이에 연필을 끼워 층을 만들래요.']),
  (294, '예정보다 긴 줄을 만난 데이트, 기다리는 시간엔 뭘 할까요?', array['보이는 글자로 끝말잇기를 해 봐요.', '손가락으로 리듬을 하나 지어요.', '지나가는 색 중 파란색만 세 봐요.']),
  (298, '상대가 좋아하는 걸 잊지 않으려고 어떤 작은 표시를 해 두고 싶나요?', array['좋아하는 색 옆에 작은 별을 그려요.', '달력에 다음에 해 볼 일을 한 줄 적어요.', '선물하고 싶은 것들을 그림으로 모아 둬요.']),
  (304, '처음 만난 두 사람이 금세 한 팀이 될 만한 활동은 뭘까요?', array['등을 맞대고 풍선을 옮기는 게임이요.', '도미노 길을 양쪽에서 이어 봐요.', '한 사람은 설명하고 한 사람은 그려요.']),
  (309, '차근차근 알려 주는 사람에게 옆에서 직접 배워 보고 싶은 건요?', array['수건이 서랍에 딱 맞게 개는 법이요.', '바람 빠진 공에 펌프 바늘 넣는 법이요.', '운동화 끈을 단단히 묶는 이중 매듭이요.']),
  (315, '가만히 같이 바라보며 말없이 쉬고 싶은 풍경은 어떤 모습인가요?', array['어항에서 이리저리 흔들리는 수초요.', '빙그르르 돌다가 멈추는 팽이요.', '창가에 걸린 모빌이 천천히 도는 모습이요.']),
  (323, '약속 전날의 나에게 고맙다고 느낄 만한 준비는 뭘까요?', array['헷갈릴 만한 갈림길을 미리 봐 뒀어요.', '빌려주기로 한 책을 먼저 가방에 넣었어요.', '신발을 손질하고 끈 길이를 맞춰 뒀어요.']),
  (326, '오래 입은 옷을 살리는 공방 데이트라면 뭘 만들어 갈까요?', array['손목만 남겨 따뜻한 컵 덮개로요.', '단추 달린 부분을 작은 방석으로요.', '실을 풀어서 줄무늬 목도리로 떠요.']),
  (334, '상대가 툭 던진 데이트 아이디어를 기억해 두는 내 방식은요?', array['달력 빈칸에 단어 두 개만 적어요.', '나한테 짧은 음성 메모를 남겨요.', '주머니 속 종이에 그림부터 그려요.']),
  (340, '공들여 뭔가 해낸 상대에게 어떤 칭찬 도장을 만들어 주고 싶어요?', array['작은 발자국이 이어지는 무늬요.', '기지개를 켜는 느긋한 고양이요.', '왕관을 비스듬히 쓴 개구리요.']),
  (348, '좋아하는 사람과 잘해야 한다는 부담 없이 함께해 보고 싶은 취미는요?', array['틀려도 계속 부는 작은 하모니카요.', '얼굴이 안 닮아도 즐거운 초상화요.', '점수는 세지 않는 실내 농구요.']),
  (354, '두 사람이 번갈아 한 장씩 접어 종이책을 만든다면 주제는요?', array['서로 쓰는 감탄사를 모은 사전이요.', '쓸데없지만 귀여운 발명품 도감이요.', '하루에 하나씩 발견한 동그라미요.']),
  (358, '서로의 취향대로 열쇠고리를 골라 주는 날, 내 취향은 무엇인가요?', array['손을 넣자마자 촉감으로 찾을 수 있게요.', '걸을 때 딸랑거리지 않는 가벼운 천이요.', '보면 바로 웃게 되는 우스운 표정이요.']),
  (362, '이불을 처음 펼친 순간처럼 기분 좋은 생활 속 순간은요?', array['새 비누에서 맨 처음 거품이 날 때요.', '깨끗이 닦은 창을 통해 하늘을 볼 때요.', '새로 간 연필심이 종이에 닿을 때요.']),
  (372, '둘이 만나서 해 볼 빙고판의 첫 번째 칸에 어떤 미션을 적을까요?', array['서로에게 어울리는 색을 골라요.', '둘 다 웃긴 표정을 한 번씩 지어요.', '같은 모양을 찾아 사진으로 찍어요.']),
  (374, '데이트 중 기분 좋은 일이 연달아 생기면 상대와 어떻게 즐기겠어요?', array['둘만 알아볼 하이파이브를 하나 만들어요.', '아까와 같은 자리에서 한 장 더 찍어요.', '오늘 제일 좋았던 순간을 하나씩 꼽아요.']),
  (381, '새 취미에 도전하는 상대를 부담 없이 응원하는 내 방식은요?', array['할 때마다 물어보기보다 먼저 말하길 기다려요.', '첫 연습에 필요한 재료를 같이 골라요.', '완성도보다 재밌었던 순간을 궁금해해요.']),
  (388, '둘이 처음 듣는 노래에도 발을 맞춰 볼 수 있는 건 어떤 놀이일까요?', array['손뼉을 주고받으며 박자를 만들어요.', '한 사람 동작을 따라 하는 거울 놀이요.', '발끝으로 하나씩 리듬을 더해 가요.']),
  (391, '메시지 말고 손으로 직접 마음을 표현한다면 어떻게 전할래요?', array['우스운 그림 한 컷 옆에 인사를 써요.', '마음에 들었던 장면을 짧은 편지에 담아요.', '책갈피를 접어 조용히 끼워 줘요.']),
  (401, '첫 대화에서 ''이런 것도 좋아해요'' 하고 소개하고 싶은 물건은요?', array['엉뚱한 각도로 기운 오리 인형이요.', '다리 길이가 조금 다른 수제 의자요.', '귀가 한쪽만 접힌 토끼 슬리퍼요.']),
  (404, '서로 그린 그림을 이어 큰 종이 한 장을 채운다면 무엇을 그릴까요?', array['굴곡이 엄청 많은 구슬 길이요.', '둘이 나란히 누울 수 있는 고래요.', '낮잠용 베개의 설계도를 그려요.']),
  (410, '데이트 날 하루가 좀 꼬였다는 상대에게 어떤 말을 해 주고 싶나요?', array['오늘은 계획 하나만 해도 충분해요.', '잠깐 같이 앉아 쉬었다 갈까요?', '누가 더 엉뚱한 하루였는지 겨뤄 볼래요?']),
  (418, '공작 데이트에서 빈 상자 하나로 둘이 만들고 싶은 장난감은요?', array['손을 넣고 그림극을 하는 작은 무대요.', '창문을 뚫은 고양이용 버스요.', '손잡이가 돌아가는 장난감 세탁기요.']),
  (421, '취미 수업에서 내 속도와 상대의 속도가 다르면 어떻게 맞출까요?', array['먼저 끝낸 쪽이 다음 재료를 챙겨요.', '어디까지 했는지 중간에 한 번 맞춰 봐요.', '각자 해 보고 마지막 단계만 같이 해요.']),
  (429, '말 대신 그림으로 주고받는 소개팅이라면 무엇을 그려 인사할까요?', array['지금 제 표정을 닮은 수줍은 고양이요.', '내가 뜨는 중인 미완성 목도리요.', '신나게 손을 흔드는 막대 사람 한 명이요.']),
  (433, '서로의 집에 처음 초대할 때 있으면 반가울 소소한 준비는요?', array['손님용 슬리퍼가 색깔별로 있었어요.', '식물 화분에 태어난 달을 써 뒀어요.', '연필꽂이 대신 머그잔을 쓰더라고요.']),
  (439, '처음 건네는 손편지의 첫 줄, 어떤 말로 시작하면 나다울까요?', array['이 얘기는 꼭 글씨로 전하고 싶었어요.', '아까 웃던 얼굴이 아직 생각나요.', '우리 다음 만남에 작은 제안이 있어요.']),
  (448, '산책 데이트 중 상대가 비눗방울 막대를 건네면 해 보고 싶은 건요?', array['커다란 방울 딱 하나를 불어 보고 싶어요.', '작은 방울을 줄줄이 날리고 싶어요.', '손바닥 위에 하나를 살며시 받아요.']),
  (452, '시간 여유가 넉넉한 데이트라면 시계는 어떻게 다루고 싶나요?', array['헤어질 시간만 맞춰 두고 가방에 넣어요.', '사진 찍을 때만 몇 시인지 살짝 봐요.', '상대가 편한 귀가 시간부터 함께 정해요.']),
  (458, '나란히 앉아 있다가 몸이 뻐근할 때 알려 주고 싶은 스트레칭은요?', array['수건 양끝을 잡고 기지개를 켜요.', '벽을 짚고 종아리를 천천히 늘려요.', '어깨를 귀까지 올렸다 툭 떨어뜨려요.']),
  (464, '함께 그림을 그리다가 상대 손에 물감이 잔뜩 묻으면요?', array['휴지를 건네고 예쁜 색이라고 얘기해요.', '손바닥 도장을 같이 찍자고 해요.', '내 손도 보여 주며 둘이 한바탕 웃어요.']),
  (472, '두 사람이 세운 작은 목표를 해냈을 때 어떤 기념을 남길까요?', array['그날 쓴 연필 끝에 날짜를 적어요.', '달력 귀퉁이에 반짝이 별을 붙여요.', '완성한 모습과 첫 시도 사진을 붙여요.']),
  (475, '오래 걸은 상대에게 쉬어 가자고 다정하게 제안하는 말은요?', array['이 벤치 자리 좋은데 같이 앉아 볼래요?', '아까 찍은 사진 여기서 구경할까요?', '저는 잠깐 쉬고 싶은데 어떠세요?']),
  (481, '서로 취미 선생님이 되는 데이트라면 무엇을 알려 줄 건가요?', array['목도리 첫 줄에 코를 잡는 법이요.', '단순한 도형으로 새를 접는 법이요.', '공 두 개로 저글링을 시작하는 법이요.']),
  (488, '둘이 만난 날 우연히 맞아떨어지면 특히 반가울 일은요?', array['필통에서 같은 색 펜이 나온 거요.', '둘 다 다음에 할 놀이를 똑같이 떠올려요.', '걷다 같은 순간에 멈춰 같은 걸 봐요.']),
  (493, '둘만의 놀이 규칙 한 줄을 새로 만든다면 어떻게 바꾸고 싶나요?', array['카드 짝을 찾으면 그 그림으로 이야기를 해요.', '끝말잇기에 동물 이름만 쓰기로 했어요.', '블록을 높게 쌓기보다 다리를 만들어요.']),
  (504, '계절이 바뀐 걸 느끼면 좋아하는 사람과 가장 먼저 나누고 싶은 건요?', array['다시 꺼낸 가벼운 겉옷의 반가움이요.', '창가에서 처음 발견한 새잎 사진이요.', '처음 손이 시렸던 저녁의 짧은 안부요.']),
  (510, '휴대폰을 잠깐 내려두고 둘이 쉬는 동안 무슨 놀이를 할까요?', array['천장 무늬에서 얼굴을 찾아낼래요.', '서로의 발가락으로 가위바위보를 해요.', '귀에 들리는 소리를 하나씩 꼽아 봐요.']),
  (516, '말 대신 짧은 메모로 서로를 챙긴다면 어떤 문장을 적어 둘래요?', array['우산은 여기에 있으니 편히 가져가요.', '이 책 뒤쪽 그림이 꼭 보여 주고 싶었어요.', '서두르지 말고 천천히 와요.']),
  (522, '마음에 드는 사람에게 제일 먼저 말하고 싶은 소소한 좋은 소식은요?', array['오래 찾던 나사가 있다는 소식이요.', '널어 둔 두꺼운 이불이 다 말랐대요.', '잃어버린 퍼즐 조각이 돌아왔어요.']),
  (525, '상대와 하루 한두 줄 일기를 바꿔 읽는다면 어떤 장면을 쓰고 싶나요?', array['손잡이를 고쳐 서랍이 잘 닫힌 얘기요.', '잠깐 고개를 들었더니 뜬 초승달이요.', '오늘 가장 크게 웃었던 어이없는 실수요.']),
  (533, '그림 실력과 상관없이 상대의 하루를 알고 싶을 때 어떤 걸 그려 달라고 할까요?', array['기분을 선 하나로 표현해 달라고 해요.', '오늘 손이 가장 많이 갔던 물건이요.', '집에 오는 길에 본 재미난 모양이요.']),
  (538, '둘 다 초보인 기술을 딱 30분만 같이 연습한다면요?', array['한 번에 박수 타이밍을 맞추고 싶어요.', '색종이 개구리를 더 멀리 뛰게 해요.', '눈 감고도 단단한 매듭을 지어 봐요.']),
  (542, '날이 바쁠 때도 놓치고 싶지 않은, 좋아하는 사람을 챙기는 습관은요?', array['헤어질 때 빌린 물건을 챙겨 줘요.', '전에 말한 중요한 날을 기억해요.', '지금은 바빠도 반갑다는 말을 남겨요.']),
  (549, '서로 아끼는 물건을 하나씩 소개한다면 나는 어느 상자를 열까요?', array['여기저기 굴러다니는 단추부터요.', '가로세로가 제각각인 미완성 엽서요.', '한 쌍씩 묶어 둔 짧은 케이블이요.']),
  (555, '서로의 메시지에만 쓰는 새 이모티콘을 만든다면 어떤 움직임이면 좋을까요?', array['녹아내렸다가 다시 일어서는 젤리요.', '기뻐서 양 귀가 프로펠러처럼 도는 토끼요.', '말없이 엄지만 쓱 내미는 달팽이요.']),
  (560, '휴대폰 없이도 외울 만큼 좋아하는 짧은 비결이 있나요?', array['테이프 끝을 접어 두면 바로 찾아요.', '실을 비누에 문지르면 바늘에 잘 꿰져요.', '신문지를 넣으면 젖은 신발이 빨리 말라요.']),
  (565, '데이트 날 예상보다 일찍 도착하면 어떤 시간을 보내고 싶나요?', array['눈에 잘 띄는 약속 장소를 확인해요.', '같이 보면 재밌을 것도 하나 찾아봐요.', '잠시 앉아 숨을 고르고 느긋하게 기다려요.']),
  (573, '첫눈에 내 취향을 보여 줄 휴대폰 배경 그림을 고른다면요?', array['그림자가 길게 드리운 단순한 계단이요.', '색연필로 그린 서툰 꽃 한 송이요.', '눈 감고 둥둥 떠 있는 작은 바다표범이요.']),
  (582, '함께 빨래를 넌다면 꼭 맡고 싶은 부분은 무엇인가요?', array['큰 이불을 같이 잡고 팡팡 터는 쪽이요.', '작은 양말 짝을 찾아 나란히 걸래요.', '셔츠 깃을 가지런히 펴는 일이 좋아요.']),
  (584, '자주 쓰는 물건에 붙인 별명 중 상대에게도 소개하고 싶은 건요?', array['자꾸 길을 잃는 로봇청소기에 ''탐험가''요.', '잘 버티는 집게에 ''악어 대장''이요.', '무슨 일이든 담는 바구니에 ''해결사''요.']),
  (590, '둘이 오래 걸리는 걸 만들고 있다면 중간에 어떻게 힘을 낼까요?', array['처음 사진과 지금 모습을 함께 봐요.', '먼저 쉬고 싶은 쪽이 쉬는 시간을 정해요.', '각자 제일 마음에 드는 부분을 짚어 줘요.']),
  (598, '가볍게 공을 주고받는 데이트에서 어떤 순간에 마음이 통할까요?', array['낮게 들어온 공을 겨우 받아 냈을 때요.', '처음 온 사람 손에 공이 정확히 갈 때요.', '세다가 숫자를 잊을 만큼 오래 이어질 때요.']),
  (604, '함께 장난감을 고치는 봉사에 나간다면 어떤 역할이 재미있을까요?', array['다 풀린 나사를 모아 제짝을 찾아요.', '고쳐진 인형 옷을 손바느질로 마무리해요.', '다시 움직이는지 아이처럼 갖고 놀아 봐요.']),
  (611, '데이트 뒤 어질러진 자리를 보고도 웃음이 날 만한 장면은요?', array['한바탕 놀고 널브러진 색색의 풍선이요.', '천을 고르느라 펼친 자투리 더미요.', '각자 벗어 둔 실내화가 모인 모습이요.']),
  (618, '좋아하는 사람과 손을 움직이며 이야기하기에 어떤 취미가 편할까요?', array['점토를 눌러 작은 그릇을 빚을래요.', '철사를 구부려 손바닥만 한 새를 만들어요.', '양모를 콕콕 찔러 납작한 얼굴을 만들래요.']),
  (624, '다섯 분 동안 서로의 책상을 바꿔 쓴다면 뭘 발견하고 싶나요?', array['상대가 제일 편하다고 고른 펜이요.', '손이 자주 가는 물건의 위치요.', '보이는 곳에 남겨 둔 응원 한마디요.']),
  (628, '서로 입은 옷에서 센스 있다고 느끼는 사소한 부분은요?', array['걷기 편한 신발을 일부러 골랐을 때요.', '좋아한다던 색을 손수건에 썼을 때요.', '직접 단 작은 배지가 보일 때요.']),
  (636, '둘이 걸을 때 상대가 잠깐 멈춰 서서 보여 주면 좋을 풍경은요?', array['웅덩이에 뒤집혀 비친 구름이요.', '보도 틈에서 고개를 내민 작은 꽃이요.', '두 그림자가 어쩌다 하나로 겹친 모습이요.']),
  (642, '손으로 만든 카드에 반짝이 장식 하나만 더한다면 어디에 붙일래요?', array['그려 놓은 상대 눈동자에 장난스럽게요.', '첫 데이트 날짜 옆에 작은 별처럼요.', '편지를 펼치면 보일 마지막 문장 옆에요.']),
  (648, '첫 만남 직전 긴장을 풀어 주는 내 작은 동작은 뭔가요?', array['발끝으로 바닥을 세 번 톡톡 쳐요.', '손을 비벼 따뜻해진 손바닥을 눈에 대요.', '두 어깨를 뒤로 쫙 펴고 고개를 들어요.']),
  (654, '둘이 함께 본 순간만 모으는 폴더를 만든다면 어떤 장면부터 담을까요?', array['둘 다 멈춰 서서 들여다본 간판이요.', '서로 몰래 완성한 낙서 두 장이요.', '풍선이 터지기 직전 얼떨떨한 표정이요.']),
  (656, '한 달 뒤 열어 볼 상자에 서로 무엇을 넣어 주고 싶나요?', array['오늘 만남에서 제일 좋았던 장면을 쓴 쪽지요.', '다음에 같이 해 볼 놀이의 준비물이요.', '한 달 뒤 서로에게 묻고 싶은 질문이요.']),
  (663, '상대와 서로 한 가지씩 소리로만 물건을 맞힌다면 뭘 고를래요?', array['달그락거리는 바둑돌 든 통이요.', '자를 책상 끝에서 튕기는 소리요.', '지퍼를 천천히 올리는 소리요.']),
  (669, '각자 씨앗을 심고 서로 자라는 과정을 나눈다면 어떻게 기록할까요?', array['날짜를 적은 아이스크림 막대를 꽂아요.', '매일 같은 각도에서 사진을 찍어요.', '어떤 잎이 될지 둘이서 그려 봐요.']),
  (677, '둘이 함께 하고 싶은 일 목록에 일부러 남겨 둘 빈칸은 무엇인가요?', array['그날 문득 끌리는 일을 위한 한 칸이요.', '친구가 제안할 놀이를 위한 빈 줄이요.', '아무것도 하지 않을 오후 한 토막이요.']),
  (679, '데이트 중 필요한 도구가 없을 때 어떤 상대와 궁리가 잘 맞을까요?', array['엉뚱한 제안도 일단 같이 해 보는 사람이요.', '가진 물건을 차례로 늘어놓아 보는 사람이요.', '안 되면 시원하게 웃고 넘기는 사람이요.']),
  (685, '만날 날을 표시해 서로 건넬 탁상 달력에 날짜 말고 뭘 넣고 싶나요?', array['하루에 하나씩 따라 그릴 작은 표정이요.', '지나고 나서 색칠할 기분 칸이요.', '한 장씩 접으면 완성되는 종이 배요.']),
  (692, '상대가 직접 쓴 카드를 받으면 어떤 글씨의 흔적에 눈이 가나요?', array['동그란 받침이 유난히 크게 나오는 거요.', '마침표를 톡 찍을 때 생기는 번짐이요.', '끝으로 갈수록 슬쩍 올라가는 모습이요.']),
  (698, '함께 만드는 물건에 끝까지 남겨 두고 싶은 서로의 흔적은요?', array['서로 하나씩 다른 색을 고른 단추요.', '바닥에 작게 포개어 쓴 두 사람의 서명이요.', '실수했지만 둘 다 웃었던 비뚤어진 선이요.']),
  (708, '둘 다 처음 보는 장난감 앞에서는 어떤 역할을 맡게 될까요?', array['뒤집어서 구르는 부분부터 살펴봐요.', '버튼마다 무슨 소리가 나는지 눌러요.', '어떻게 움직일지 먼저 서로 맞혀 봐요.']),
  (710, '마음에 드는 사람이 채워 갈 스티커 달력이라면 어떤 날을 표시할까요?', array['하루 한 번 크게 웃었을 때 붙여요.', '고민하던 일을 시작한 첫 순간이요.', '새로 배운 단어 옆에 하나씩 붙여요.']),
  (720, '상대와 눈 감고 종이비행기를 접는다면 나는 어떤 재미를 먼저 찾을까요?', array['삐뚤어도 한 번 떠오르면 성공이에요.', '웃긴 모양에 어울릴 이름부터 붙여요.', '날개 끝을 다시듬어 멀리 날려 볼래요.']),
  (726, '즐거웠던 약속이 끝날 때 둘만의 작별 인사를 만든다면 어떤 게 좋나요?', array['손바닥을 맞대고 손끝까지 가볍게 털어요.', '오늘을 나타내는 낱말을 하나씩 외쳐요.', '다음 인사말을 상대에게 하나씩 정해 줘요.']),
  (732, '오늘 내 모습 중 상대에게 슬쩍 자랑하고 싶은 장면은요?', array['무너지는 블록을 한 손으로 살렸어요.', '오래 묵은 얼룩을 결국 지워 냈어요.', '도움 없이 자전거 안장 높이를 맞췄어요.']);
